type 'a flexiple = | One of 'a | Num of int * 'a ;;let rec last : 'a list -> 'a option = function  | [] -> None  | [x] -> Some x  | _::t -> last t;;let rec lastTwo : 'a list -> ('a * 'a) option = function  | [] | [_] -> None  | [x ; y] -> Some (x , y)  | _::t -> lastTwo t;;let rec at (l : 'a list) (n : int) : 'a option = match l with  | [] -> None  | h :: _ when n = 0 -> Some h  | _::t -> at t (n - 1);;let length (l : 'a list) : int =  let rec aux len l' = match l' with    | [] -> len    | _::t -> aux (len + 1) t  in aux 0 l;;let rev (l : 'a list) : 'a list =  let rec aux acc = function    | [] -> acc    | h::t -> aux (h::acc) t  in aux [] l;;let isPalindrome (l : 'a list) : bool =  l = (rev l);;let encode (l : 'a list) : (int * 'a) list =  let rec aux occ acc = function    | [] -> acc    | [x] -> (occ + 1 , x)::acc    | h::t -> let h'::_ = t in        if h = h'        then aux (occ + 1) acc t        else aux 0 ((occ+1 , h)::acc) t  in rev (aux 0 [] l);;let encodeMod (l : 'a list) : ('a flexiple) list =  let rec aux count acc = function    | [] -> acc    | [x] -> if count = 0 then (One x)::acc else (Num (count + 1 , x))::acc    | h::t -> let h'::_ = t in        if h = h'        then aux (count + 1) acc t        else if count = 0 then aux 0 ((One h)::acc) t        else aux 0 ((Num (count + 1 , h))::acc) t  in rev (aux 0 [] l);;